/**
 * @brief Unescape a JSON string, can work in-place if src == dst
 * @param src Source string with escape sequences
 * @param dst Destination buffer for unescaped string (can be same as src)
 * @param src_len Length of source string (length of the JSON string token)
 * @param dst_size Size of destination buffer (including space for null terminator)
 * @return int Number of bytes written to destination (excluding null),
 *             -ENOMEM if buffer is too small, or -EINVAL on invalid escape sequence.
 */
static int json_unescape_string(const char *src, char *dst, size_t src_len, size_t dst_size)
{
	const char *src_end = src + src_len;
	char *dst_start = dst;
	char *dst_curr = dst; /* Use dst_curr to track current write position */
	char *dst_limit = dst_start + dst_size - 1; /* Point to last available byte (for null) */

	while (src < src_end) {
		if (dst_curr >= dst_limit) {
			/* Not enough space for the unescaped string (even before null terminator) */
			return -ENOMEM;
		}

		if (*src == '\\') {
			src++;
			if (src >= src_end) {
				/* Incomplete escape sequence at end of string */
				return -EINVAL;
			}

			switch (*src) {
			case '"':
				*dst_curr++ = '"';
				break;
			case '\\':
				*dst_curr++ = '\\';
				break;
			case '/':
				*dst_curr++ = '/';
				break;
			case 'b':
				*dst_curr++ = '\b';
				break;
			case 'f':
				*dst_curr++ = '\f';
				break;
			case 'n':
				*dst_curr++ = '\n';
				break;
			case 'r':
				*dst_curr++ = '\r';
				break;
			case 't':
				*dst_curr++ = '\t';
				break;
			case 'u':
				/* Unicode escape sequence \uXXXX.
				 * The current JSON library design does not unescape these
				 * into actual Unicode characters, but rather treats them
				 * as literal '\uXXXX' sequences in the C string.
				 * This matches existing test expectations (e.g., "z\\uABCD").
				 * So, we copy the entire 6-character sequence.
				 */
				if (src + 4 >= src_end) {
					/* Incomplete unicode escape sequence */
					return -EINVAL;
				}
				if (dst_curr + 5 >= dst_limit) { /* Need 6 chars: '\u' + 4 hex */
					return -ENOMEM;
				}
				*dst_curr++ = '\\';
				*dst_curr++ = 'u';
				for (int i = 0; i < 4; ++i) {
					if (!isxdigit(src[i + 1])) {
						return -EINVAL; /* Invalid hex digit */
					}
					*dst_curr++ = src[i + 1];
				}
				src += 4; /* Advance src past the 4 hex digits */
				break;
			default:
				/* Unknown escape sequence.
				 * The lexer (lexer_string) should ideally catch invalid escape
				 * sequences (e.g., "\X") and emit JSON_TOK_ERROR.
				 * If we reach here, it implies a valid JSON string with an
				 * escape sequence not explicitly handled above (e.g., a future
				 * extension or a character that is technically allowed to be
				 * escaped but not commonly used). For robustness, we copy the
				 * backslash and the character as-is.
				 */
				if (dst_curr + 1 >= dst_limit) {
					return -ENOMEM;
				}
				*dst_curr++ = '\\';
				*dst_curr++ = *src;
				break;
			}
			src++; /* Advance src past the escaped character */
		} else {
			*dst_curr++ = *src++;
		}
	}

	*dst_curr = '\0';
	return dst_curr - dst_start;
}

static int decode_string_buf(const struct json_token *token, char *str, size_t size)
{
	/* The token->start and token->end define the raw string from the JSON,
	 * including any escape sequences. We need to unescape this into 'str'.
	 * 'size' is the total buffer size for 'str', including the null terminator.
	 */
	size_t raw_json_str_len = token->end - token->start;
	int unescaped_len;

	/* Call json_unescape_string to perform the unescaping.
	 * It will write into 'str' and null-terminate it,
	 * returning the length of the unescaped string (excluding null).
	 * It will return -ENOMEM if 'str' buffer is too small.
	 * It will return -EINVAL if the JSON string contains invalid escape sequences.
