	unescaped_len = json_unescape_string(token->start, str, raw_json_str_len, size);

	if (unescaped_len < 0) {
		return unescaped_len; /* Propagate -ENOMEM or -EINVAL */
	}

	/* If unescaped_len is non-negative, it means the string fit and was null-terminated. */
	return 0;
